 1→import { prisma } from '@tpmjs/db';
 2→import { betterAuth } from 'better-auth';
 3→import { prismaAdapter } from 'better-auth/adapters/prisma';
 4→import { sendResetPasswordEmail, sendVerificationEmail } from './email';
 5→
 6→// Determine base URL for auth - MUST match the domain users are browsing on
 7→// VERCEL_URL is the deployment URL (e.g., tpmjs-xxx.vercel.app), not the custom domain
 8→// So we prioritize BETTER_AUTH_URL or fall back to the production domain
 9→const getBaseURL = () => {
10→  if (process.env.BETTER_AUTH_URL) return process.env.BETTER_AUTH_URL;
11→  // Local development
12→  if (process.env.NODE_ENV === 'development') return 'http://localhost:3000';
13→  // In production, always use the custom domain, not VERCEL_URL
14→  if (process.env.VERCEL_ENV === 'production') return 'https://tpmjs.com';
15→  // For preview deployments, use the Vercel URL
16→  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
17→  return 'https://tpmjs.com';
18→};
19→
20→export const auth = betterAuth({
21→  secret: process.env.BETTER_AUTH_SECRET,
22→  baseURL: getBaseURL(),
23→  database: prismaAdapter(prisma, {
24→    provider: 'postgresql',
25→  }),
26→  emailAndPassword: {
27→    enabled: true,
28→    requireEmailVerification: true,
29→    sendResetPassword: async ({ user, url }) => {
30→      await sendResetPasswordEmail(user.email, url);
31→    },
32→  },
33→  emailVerification: {
34→    sendVerificationEmail: async ({ user, url }) => {
35→      await sendVerificationEmail(user.email, url);
36→    },
37→    autoSignInAfterVerification: true,
38→    sendOnSignUp: true,
39→  },
40→  session: {
41→    expiresIn: 60 * 60 * 24 * 7, // 7 days
42→    updateAge: 60 * 60 * 24, // 1 day
43→    cookieCache: {
44→      enabled: true,
45→      maxAge: 60 * 5, // 5 minutes
46→    },
47→  },
48→  trustedOrigins: ['https://tpmjs.com', 'http://localhost:3000', 'http://localhost:3002'],
49→  databaseHooks: {
50→    user: {
51→      create: {
52→        after: async (user) => {
53→          // Update signup source after user creation
54→          // The provider is determined by the account that was just created
55→          try {
56→            const account = await prisma.account.findFirst({
57→              where: { userId: user.id },
58→              orderBy: { createdAt: 'desc' },
59→              select: { providerId: true },
60→            });
61→            const source = account?.providerId || 'direct';
62→            await prisma.user.update({
63→              where: { id: user.id },
64→              data: { signupSource: source },
65→            });
66→          } catch (error) {
67→            console.error('[auth] Failed to set signup source:', error);
68→          }
69→        },
70→      },
71→    },
72→  },
73→  advanced: {
74→    defaultCookieAttributes: {
75→      sameSite: 'lax',
76→      secure: process.env.NODE_ENV !== 'development',
77→      httpOnly: true,
78→    },
79→  },
80→});
81→
82→export type Session = typeof auth.$Infer.Session;
