  1→'use client';
  2→
  3→import { suggestUsername } from '@tpmjs/types/user';
  4→import { Button } from '@tpmjs/ui/Button/Button';
  5→import { Icon } from '@tpmjs/ui/Icon/Icon';
  6→import { Input } from '@tpmjs/ui/Input/Input';
  7→import { Label } from '@tpmjs/ui/Label/Label';
  8→import Link from 'next/link';
  9→import { useCallback, useEffect, useState } from 'react';
 10→import { signUp } from '~/lib/auth-client';
 11→
 12→interface UsernameCheckResult {
 13→  available: boolean;
 14→  reason?: string;
 15→}
 16→
 17→export default function SignUpPage() {
 18→  const [name, setName] = useState('');
 19→  const [username, setUsername] = useState('');
 20→  const [email, setEmail] = useState('');
 21→  const [password, setPassword] = useState('');
 22→  const [error, setError] = useState('');
 23→  const [loading, setLoading] = useState(false);
 24→
 25→  // Username availability state
 26→  const [usernameCheck, setUsernameCheck] = useState<UsernameCheckResult | null>(null);
 27→  const [checkingUsername, setCheckingUsername] = useState(false);
 28→  const [usernameEdited, setUsernameEdited] = useState(false);
 29→
 30→  // Auto-generate username from name (only if user hasn't manually edited it)
 31→  useEffect(() => {
 32→    if (!usernameEdited && name.length >= 2) {
 33→      const suggested = suggestUsername(name);
 34→      if (suggested.length >= 3) {
 35→        setUsername(suggested);
 36→      }
 37→    }
 38→  }, [name, usernameEdited]);
 39→
 40→  // Debounced username availability check
 41→  const checkUsernameAvailability = useCallback(async (usernameToCheck: string) => {
 42→    if (usernameToCheck.length < 3) {
 43→      setUsernameCheck({ available: false, reason: 'Username must be at least 3 characters' });
 44→      return;
 45→    }
 46→
 47→    setCheckingUsername(true);
 48→    try {
 49→      const response = await fetch(
 50→        `/api/user/username/check?username=${encodeURIComponent(usernameToCheck)}`
 51→      );
 52→      const data = await response.json();
 53→
 54→      if (data.success) {
 55→        setUsernameCheck(data.data);
 56→      } else {
 57→        setUsernameCheck({ available: false, reason: 'Failed to check availability' });
 58→      }
 59→    } catch {
 60→      setUsernameCheck({ available: false, reason: 'Failed to check availability' });
 61→    } finally {
 62→      setCheckingUsername(false);
 63→    }
 64→  }, []);
 65→
 66→  // Debounce the username check
 67→  useEffect(() => {
 68→    if (username.length < 3) {
 69→      setUsernameCheck(null);
 70→      return;
 71→    }
 72→
 73→    const timeout = setTimeout(() => {
 74→      checkUsernameAvailability(username);
 75→    }, 300);
 76→
 77→    return () => clearTimeout(timeout);
 78→  }, [username, checkUsernameAvailability]);
 79→
 80→  function handleUsernameChange(e: React.ChangeEvent<HTMLInputElement>) {
 81→    setUsernameEdited(true);
 82→    // Force lowercase and remove invalid characters
 83→    const value = e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '');
 84→    setUsername(value);
 85→  }
 86→
 87→  async function handleSubmit(e: React.FormEvent) {
 88→    e.preventDefault();
 89→    setError('');
 90→
 91→    // Validate username
 92→    if (!username || username.length < 3) {
 93→      setError('Please choose a valid username (at least 3 characters)');
 94→      return;
 95→    }
 96→
 97→    if (usernameCheck && !usernameCheck.available) {
 98→      setError(usernameCheck.reason || 'Please choose a different username');
 99→      return;
100→    }
101→
102→    setLoading(true);
103→
104→    try {
105→      const { data, error: signUpError } = await signUp.email({
106→        name,
107→        email,
108→        password,
109→      });
110→
111→      if (signUpError) {
112→        console.error('Sign up error:', signUpError);
113→        setError(signUpError.message || 'Failed to create account');
114→        setLoading(false);
115→        return;
116→      }
117→
118→      if (data) {
119→        // Account created - now set the username (REQUIRED)
120→        let usernameSet = false;
121→        let retries = 3;
122→
123→        while (!usernameSet && retries > 0) {
124→          try {
125→            const profileResponse = await fetch('/api/user/profile', {
126→              method: 'PATCH',
127→              headers: { 'Content-Type': 'application/json' },
128→              body: JSON.stringify({ username }),
129→            });
130→
131→            if (profileResponse.ok) {
132→              usernameSet = true;
133→            } else {
134→              const errorData = await profileResponse.json();
135→              if (errorData.error === 'This username is already taken') {
136→                // Username was taken between check and signup
137→                setError('Username was taken. Please choose a different one and try signing in.');
138→                setLoading(false);
139→                return;
140→              }
141→              retries--;
142→              if (retries > 0) {
143→                await new Promise((resolve) => setTimeout(resolve, 500));
144→              }
145→            }
146→          } catch {
147→            retries--;
148→            if (retries > 0) {
149→              await new Promise((resolve) => setTimeout(resolve, 500));
150→            }
151→          }
152→        }
153→
154→        if (!usernameSet) {
155→          // Critical: Username couldn't be set, but account exists
156→          // Redirect to profile page to set it manually
157→          console.error('Failed to set username after retries');
158→          window.location.href = '/dashboard/settings/profile?setup=1';
159→          return;
160→        }
161→
162→        // Redirect to verify email page
163→        window.location.href = '/verify-email';
164→      }
165→    } catch {
166→      setError('An unexpected error occurred');
167→      setLoading(false);
168→    }
169→  }
170→
171→  return (
172→    <div className="space-y-6">
173→      <div className="text-center">
174→        <h1 className="text-2xl font-bold text-foreground">Create Account</h1>
175→        <p className="text-foreground-secondary mt-2">Join TPMJS to access your dashboard</p>
176→      </div>
177→
178→      <form onSubmit={handleSubmit} className="space-y-4">
179→        {error && (
180→          <div className="bg-error/10 border border-error/20 text-error px-4 py-3 rounded-md text-sm">
181→            {error}
182→          </div>
183→        )}
184→
185→        <div>
186→          <Label htmlFor="name">Name</Label>
187→          <Input
188→            id="name"
189→            type="text"
190→            value={name}
191→            onChange={(e) => setName(e.target.value)}
192→            required
193→            placeholder="Your name"
194→          />
195→        </div>
196→
197→        <div>
198→          <Label htmlFor="username">Username</Label>
199→          <div className="relative">
200→            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-foreground-secondary">
201→              @
202→            </div>
203→            <Input
204→              id="username"
205→              type="text"
206→              value={username}
207→              onChange={handleUsernameChange}
208→              required
209→              minLength={3}
210→              maxLength={30}
211→              className="pl-7 pr-10"
212→              placeholder="username"
213→            />
214→            {/* Status indicator */}
215→            <div className="absolute inset-y-0 right-0 pr-3 flex items-center">
216→              {checkingUsername && (
217→                <Icon icon="loader" size="sm" className="animate-spin text-foreground-secondary" />
218→              )}
219→              {!checkingUsername && usernameCheck?.available && (
220→                <Icon icon="check" size="sm" className="text-success" />
221→              )}
222→              {!checkingUsername &&
223→                usernameCheck &&
224→                !usernameCheck.available &&
225→                username.length >= 3 && <Icon icon="x" size="sm" className="text-error" />}
226→            </div>
227→          </div>
228→          {/* Username availability message */}
229→          {username.length >= 3 && usernameCheck && !usernameCheck.available && (
230→            <p className="mt-1 text-xs text-error">{usernameCheck.reason}</p>
231→          )}
232→          {username.length >= 3 && usernameCheck?.available && (
233→            <p className="mt-1 text-xs text-success">Username available</p>
234→          )}
235→          {username && (
236→            <p className="mt-1 text-xs text-foreground-tertiary">
237→              Your profile: tpmjs.com/@{username}
238→            </p>
239→          )}
240→        </div>
241→
242→        <div>
243→          <Label htmlFor="email">Email</Label>
244→          <Input
245→            id="email"
246→            type="email"
247→            value={email}
248→            onChange={(e) => setEmail(e.target.value)}
249→            required
250→            placeholder="you@example.com"
251→          />
252→        </div>
253→
254→        <div>
255→          <Label htmlFor="password">Password</Label>
256→          <Input
257→            id="password"
258→            type="password"
259→            value={password}
260→            onChange={(e) => setPassword(e.target.value)}
261→            required
262→            minLength={8}
263→            placeholder="At least 8 characters"
264→          />
265→        </div>
266→
267→        <Button
268→          type="submit"
269→          disabled={loading || (usernameCheck !== null && !usernameCheck.available)}
270→          loading={loading}
271→          className="w-full"
272→        >
273→          {loading ? 'Creating account...' : 'Create Account'}
274→        </Button>
275→      </form>
276→
277→      <p className="text-center text-sm text-foreground-secondary">
278→        Already have an account?{' '}
279→        <Link href="/sign-in" className="text-foreground hover:underline font-medium">
280→          Sign in
281→        </Link>
282→      </p>
283→    </div>
284→  );
285→}
