  1→import { prisma } from '@tpmjs/db';
  2→import { RESERVED_USERNAMES, UpdateUserProfileSchema, USERNAME_REGEX } from '@tpmjs/types/user';
  3→import { type NextRequest, NextResponse } from 'next/server';
  4→
  5→import { authenticateRequest } from '~/lib/api-keys/middleware';
  6→
  7→export const runtime = 'nodejs';
  8→export const dynamic = 'force-dynamic';
  9→
 10→/**
 11→ * GET /api/user/profile
 12→ * Get the current user's profile
 13→ */
 14→export async function GET(): Promise<NextResponse> {
 15→  try {
 16→    const authResult = await authenticateRequest();
 17→    if (!authResult.authenticated || !authResult.userId) {
 18→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 19→    }
 20→
 21→    const user = await prisma.user.findUnique({
 22→      where: { id: authResult.userId },
 23→      select: {
 24→        id: true,
 25→        name: true,
 26→        username: true,
 27→        email: true,
 28→        image: true,
 29→        createdAt: true,
 30→      },
 31→    });
 32→
 33→    if (!user) {
 34→      return NextResponse.json({ success: false, error: 'User not found' }, { status: 404 });
 35→    }
 36→
 37→    return NextResponse.json({
 38→      success: true,
 39→      data: user,
 40→    });
 41→  } catch (error) {
 42→    console.error('Failed to get user profile:', error);
 43→    return NextResponse.json({ success: false, error: 'Failed to get profile' }, { status: 500 });
 44→  }
 45→}
 46→
 47→/**
 48→ * PATCH /api/user/profile
 49→ * Update the current user's profile
 50→ */
 51→export async function PATCH(request: NextRequest): Promise<NextResponse> {
 52→  try {
 53→    const authResult = await authenticateRequest();
 54→    if (!authResult.authenticated || !authResult.userId) {
 55→      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 56→    }
 57→
 58→    const body = await request.json();
 59→    const result = UpdateUserProfileSchema.safeParse(body);
 60→
 61→    if (!result.success) {
 62→      return NextResponse.json(
 63→        {
 64→          success: false,
 65→          error: 'Invalid input',
 66→          details: result.error.flatten().fieldErrors,
 67→        },
 68→        { status: 400 }
 69→      );
 70→    }
 71→
 72→    const { name, username, image } = result.data;
 73→
 74→    // If updating username, validate availability
 75→    if (username) {
 76→      // Check if reserved
 77→      if ((RESERVED_USERNAMES as readonly string[]).includes(username)) {
 78→        return NextResponse.json(
 79→          {
 80→            success: false,
 81→            error: 'This username is reserved',
 82→          },
 83→          { status: 400 }
 84→        );
 85→      }
 86→
 87→      // Check regex
 88→      if (!USERNAME_REGEX.test(username)) {
 89→        return NextResponse.json(
 90→          {
 91→            success: false,
 92→            error: 'Username must be lowercase alphanumeric with single hyphens only',
 93→          },
 94→          { status: 400 }
 95→        );
 96→      }
 97→
 98→      // Check if already taken by another user
 99→      const existingUser = await prisma.user.findFirst({
100→        where: {
101→          username,
102→          NOT: { id: authResult.userId },
103→        },
104→        select: { id: true },
105→      });
106→
107→      if (existingUser) {
108→        return NextResponse.json(
109→          {
110→            success: false,
111→            error: 'This username is already taken',
112→          },
113→          { status: 400 }
114→        );
115→      }
116→    }
117→
118→    const updatedUser = await prisma.user.update({
119→      where: { id: authResult.userId },
120→      data: {
121→        ...(name !== undefined && { name }),
122→        ...(username !== undefined && { username }),
123→        ...(image !== undefined && { image }),
124→      },
125→      select: {
126→        id: true,
127→        name: true,
128→        username: true,
129→        email: true,
130→        image: true,
131→        createdAt: true,
132→      },
133→    });
134→
135→    return NextResponse.json({
136→      success: true,
137→      data: updatedUser,
138→    });
139→  } catch (error) {
140→    console.error('Failed to update user profile:', error);
141→    return NextResponse.json(
142→      { success: false, error: 'Failed to update profile' },
143→      { status: 500 }
144→    );
145→  }
146→}
