  1→/**
  2→ * Discord Summary Cron Endpoint
  3→ *
  4→ * Triggers the Discord summary agent to:
  5→ * 1. Read messages from the past 24 hours
  6→ * 2. Summarize them
  7→ * 3. Post the summary to a Discord channel
  8→ *
  9→ * Schedule: Daily at 9 AM UTC (configured in vercel.json)
 10→ */
 11→
 12→import { prisma } from '@tpmjs/db';
 13→import { type NextRequest, NextResponse } from 'next/server';
 14→import { env } from '~/env';
 15→
 16→export const runtime = 'nodejs';
 17→export const dynamic = 'force-dynamic';
 18→export const maxDuration = 300; // 5 minutes for agent execution
 19→
 20→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Cron job with multiple steps and error handling
 21→export async function POST(request: NextRequest) {
 22→  const startTime = Date.now();
 23→
 24→  // 1. Verify cron secret
 25→  const authHeader = request.headers.get('authorization');
 26→  const token = authHeader?.replace('Bearer ', '');
 27→
 28→  if (env.CRON_SECRET && token !== env.CRON_SECRET) {
 29→    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
 30→  }
 31→
 32→  // 2. Check required env vars
 33→  const agentId = env.DISCORD_SUMMARY_AGENT_ID;
 34→  const guildId = env.DISCORD_GUILD_ID;
 35→  const summaryChannelId = env.DISCORD_SUMMARY_CHANNEL_ID;
 36→
 37→  if (!agentId || !guildId || !summaryChannelId) {
 38→    const missing = [];
 39→    if (!agentId) missing.push('DISCORD_SUMMARY_AGENT_ID');
 40→    if (!guildId) missing.push('DISCORD_GUILD_ID');
 41→    if (!summaryChannelId) missing.push('DISCORD_SUMMARY_CHANNEL_ID');
 42→
 43→    return NextResponse.json(
 44→      { success: false, error: `Missing required env vars: ${missing.join(', ')}` },
 45→      { status: 500 }
 46→    );
 47→  }
 48→
 49→  try {
 50→    // 3. Verify agent exists and get owner info
 51→    const agent = await prisma.agent.findUnique({
 52→      where: { id: agentId },
 53→      select: {
 54→        id: true,
 55→        uid: true,
 56→        name: true,
 57→        user: { select: { username: true } },
 58→      },
 59→    });
 60→
 61→    if (!agent) {
 62→      return NextResponse.json(
 63→        { success: false, error: `Agent not found: ${agentId}` },
 64→        { status: 404 }
 65→      );
 66→    }
 67→
 68→    if (!agent.user.username || !agent.uid) {
 69→      return NextResponse.json(
 70→        { success: false, error: 'Agent owner has no username or agent has no UID' },
 71→        { status: 500 }
 72→      );
 73→    }
 74→
 75→    // 4. Get or create a conversation for this cron job
 76→    // Use a fixed slug for the cron job so we reuse the same conversation
 77→    const cronSlug = 'discord-summary-cron';
 78→
 79→    let conversation = await prisma.conversation.findUnique({
 80→      where: { agentId_slug: { agentId, slug: cronSlug } },
 81→    });
 82→
 83→    if (!conversation) {
 84→      conversation = await prisma.conversation.create({
 85→        data: {
 86→          agentId,
 87→          slug: cronSlug,
 88→          title: 'Daily Discord Summary',
 89→        },
 90→      });
 91→    }
 92→
 93→    // 5. Build the prompt for the agent
 94→    const prompt = `Please summarize the Discord server activity from the past 24 hours.
 95→
 96→Use the discordReadTool with these parameters:
 97→- guildId: "${guildId}"
 98→- hours: 24
 99→- excludeBots: true
100→
101→After reading the messages, analyze them and create a summary that includes:
102→- Key discussions and topics from each active channel
103→- Important decisions or announcements
104→- Action items or follow-ups mentioned
105→- Notable conversations or questions
106→
107→Then use the discordPostTool to post the summary to channel "${summaryChannelId}" as a rich embed with:
108→- title: "📊 Daily Server Summary"
109→- color: 5793266 (Discord blurple)
110→- A well-formatted description with the summary
111→- footer: Include the date range and message count
112→
113→If there are no messages in the past 24 hours, post a brief message saying the server was quiet.`;
114→
115→    // 6. Call the agent conversation endpoint (new URL format)
116→    const baseUrl = env.BETTER_AUTH_URL || `http://localhost:${process.env.PORT || 3000}`;
117→    const response = await fetch(
118→      `${baseUrl}/api/${agent.user.username}/agents/${agent.uid}/conversation/${conversation.id}`,
119→      {
120→        method: 'POST',
121→        headers: {
122→          'Content-Type': 'application/json',
123→        },
124→        body: JSON.stringify({ message: prompt }),
125→      }
126→    );
127→
128→    // 7. Consume the SSE stream to let it complete
129→    // We don't need to parse the events, just ensure the request completes
130→    if (response.body) {
131→      const reader = response.body.getReader();
132→      try {
133→        while (true) {
134→          const { done } = await reader.read();
135→          if (done) break;
136→        }
137→      } finally {
138→        reader.releaseLock();
139→      }
140→    }
141→
142→    const durationMs = Date.now() - startTime;
143→
144→    // 8. Log the result
145→    await prisma.syncLog.create({
146→      data: {
147→        source: 'discord-summary',
148→        status: response.ok ? 'success' : 'error',
149→        processed: 1,
150→        skipped: 0,
151→        errors: response.ok ? 0 : 1,
152→        message: response.ok
153→          ? 'Discord summary completed'
154→          : `Agent request failed: ${response.status}`,
155→        metadata: {
156→          durationMs,
157→          agentId,
158→          conversationId: conversation.id,
159→          guildId,
160→          summaryChannelId,
161→        },
162→      },
163→    });
164→
165→    return NextResponse.json({
166→      success: response.ok,
167→      data: {
168→        agentId,
169→        agentName: agent.name,
170→        conversationId: conversation.id,
171→        durationMs,
172→      },
173→    });
174→  } catch (error) {
175→    const durationMs = Date.now() - startTime;
176→
177→    // Log error
178→    await prisma.syncLog.create({
179→      data: {
180→        source: 'discord-summary',
181→        status: 'error',
182→        processed: 0,
183→        skipped: 0,
184→        errors: 1,
185→        message: error instanceof Error ? error.message : 'Unknown error',
186→        metadata: {
