import { prisma } from '@tpmjs/db';
import { betterAuth } from 'better-auth';
import { prismaAdapter } from 'better-auth/adapters/prisma';
import { sendResetPasswordEmail, sendVerificationEmail } from './email';

// Determine base URL for auth - MUST match the domain users are browsing on
// VERCEL_URL is the deployment URL (e.g., tpmjs-xxx.vercel.app), not the custom domain
// So we prioritize BETTER_AUTH_URL or fall back to the production domain
const getBaseURL = () => {
  if (process.env.BETTER_AUTH_URL) return process.env.BETTER_AUTH_URL;
  // Local development
  if (process.env.NODE_ENV === 'development') return 'http://localhost:3000';
  // In production, always use the custom domain, not VERCEL_URL
  if (process.env.VERCEL_ENV === 'production') return 'https://tpmjs.com';
  // For preview deployments, use the Vercel URL
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
  return 'https://tpmjs.com';
};

export const auth = betterAuth({
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: getBaseURL(),
  database: prismaAdapter(prisma, {
    provider: 'postgresql',
  }),
  emailAndPassword: {
    enabled: true,
    requireEmailVerification: true,
    sendResetPassword: async ({ user, url }) => {
      await sendResetPasswordEmail(user.email, url);
    },
  },
  emailVerification: {
    sendVerificationEmail: async ({ user, url }) => {
      await sendVerificationEmail(user.email, url);
    },
    autoSignInAfterVerification: true,
    sendOnSignUp: true,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7, // 7 days
    updateAge: 60 * 60 * 24, // 1 day
    cookieCache: {
      enabled: true,
      maxAge: 60 * 5, // 5 minutes
    },
  },
  trustedOrigins: ['https://tpmjs.com', 'http://localhost:3000', 'http://localhost:3002'],
  databaseHooks: {
    user: {
      create: {
        after: async (user) => {
          // Update signup source after user creation
          // The provider is determined by the account that was just created
          try {
            const account = await prisma.account.findFirst({
              where: { userId: user.id },
              orderBy: { createdAt: 'desc' },
              select: { providerId: true },
            });
            const source = account?.providerId || 'direct';
            await prisma.user.update({
              where: { id: user.id },
              data: { signupSource: source },
            });
          } catch (error) {
            console.error('[auth] Failed to set signup source:', error);
          }
        },
      },
    },
  },
  advanced: {
    defaultCookieAttributes: {
      sameSite: 'lax',
      secure: process.env.NODE_ENV !== 'development',
      httpOnly: true,
    },
  },
});

export type Session = typeof auth.$Infer.Session;

import { createEnv } from '@tpmjs/env';
import { z } from 'zod';

export const env = createEnv({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  NEXT_PUBLIC_API_URL: z.string().url().optional(),
  CRON_SECRET: z.string().min(32).optional(), // Required for Vercel Cron security
  RAILWAY_EXECUTOR_URL: z
    .string()
    .url()
    .default('https://endearing-commitment-production.up.railway.app'), // Railway service for health checks

  // Better Auth
  BETTER_AUTH_SECRET: z.string().min(32).optional(), // Required for session encryption
  BETTER_AUTH_URL: z.string().url().optional(), // Base URL for auth callbacks

  // Resend (Email)
  RESEND_API_KEY: z.string().startsWith('re_').optional(), // Resend API key for sending emails

  // Discord Summary Agent
  DISCORD_SUMMARY_AGENT_ID: z.string().optional(), // Agent ID for Discord summary cron
  DISCORD_GUILD_ID: z.string().optional(), // Discord server ID to summarize
  DISCORD_SUMMARY_CHANNEL_ID: z.string().optional(), // Channel to post summaries to

  // Sentry
  SENTRY_DSN: z.string().url().optional(), // Sentry DSN for server-side error reporting
  NEXT_PUBLIC_SENTRY_DSN: z.string().url().optional(), // Sentry DSN for client-side error reporting
  SENTRY_ORG: z.string().optional(), // Sentry organization slug
  SENTRY_PROJECT: z.string().optional(), // Sentry project slug
  SENTRY_AUTH_TOKEN: z.string().optional(), // Sentry auth token for source map uploads
});

